//! @generated by xtask split-potions.
use super::prelude::*;

/// DropletOfPrecognition — choose 1 card from the draw pile and move it
/// to hand. Mirrors C# `DropletOfPrecognition.OnUse`:
/// `CardSelectCmd.FromSimpleGrid(draw cards ordered by Rarity then Id,
/// prefs(1))` → `CardPileCmd.Add(chosen, Hand)`. Opens an
/// `AddFromDrawByType` choice (the resolver is generic: it removes the
/// chosen uid from `draw` and pushes it onto `hand`) over the whole
/// draw pile, ordered by (C# rarity ordinal, Entry string) to mirror the
/// C# grid order (`orderby c.Rarity, c.Id`, DropletOfPrecognition.cs:22-24).
/// Single-pick, not skippable. Empty draw pile ⇒ no-op. Bead `sts2-rs-19hm7`.
pub(crate) fn drink_droplet_of_precognition(
    state: &mut CombatState,
    _target: Option<u8>,
) -> EffectResult {
    if state.player.draw.is_empty() {
        return EffectResult::Resolved;
    }
    // C# `DropletOfPrecognition.cs:22-24` orders the grid `orderby c.Rarity,
    // c.Id`, where `c.Id` (ModelId) ties break on the `Entry` STRING via
    // ordinal comparison — NOT the `CardId` enum discriminant. Sorting by
    // `card_id as u32` instead heads the grid with the enum-0 card (Strike),
    // whereas C# heads with the alphabetically-first Entry (e.g. BASH <
    // STRIKE_IRONCLAD). With the deterministic option[0] picker this flips
    // which card moves draw → hand, so the key must mirror C# exactly:
    // (CardRarity ordinal as PRIMARY, then Entry string). `to_python_name()`
    // returns the C# `Entry` slug verbatim. Bead `sts2-rs-19hm7`.
    let mut ordered: Vec<sts2_core::CardUid> = state.player.draw.to_vec();
    ordered.sort_by(|&a, &b| {
        let id_a = state.cards[a.0.get() as usize - 1].card_id;
        let id_b = state.cards[b.0.get() as usize - 1].card_id;
        csharp_rarity_ordinal(id_a)
            .cmp(&csharp_rarity_ordinal(id_b))
            .then_with(|| id_a.to_python_name().cmp(id_b.to_python_name()))
    });
    // C# `CardSelectCmd.FromSimpleGrid` auto-resolves inline when
    // `!RequireManualConfirmation && cards.Count <= MinSelect` (CardSelectCmd.cs:232-235).
    // DropletOfPrecognition uses `prefs(1)` (Min==Max==1, no manual confirm), so a
    // draw pile of exactly 1 card is added directly to hand with NO decision point —
    // the real game never presents the prompt. Rust previously only short-circuited
    // on an EMPTY draw pile, surfacing a phantom 1-option `card_select`.
    if ordered.len() <= 1 {
        for uid in &ordered {
            if let Some(pos) = state.player.draw.iter().position(|u| u == uid) {
                let card = state.player.draw.remove(pos);
                state.player.hand.push(card);
            }
        }
        return EffectResult::Resolved;
    }
    let options: Vec<sts2_core::ChoiceOption> = ordered
        .iter()
        .map(|&uid| {
            let idx = uid.0.get() as usize - 1;
            sts2_core::ChoiceOption {
                card_id: state.cards[idx].card_id,
                upgraded: state.cards[idx].upgraded,
                card_uid: Some(uid),
                source_pile: Some(sts2_core::cards::PileKind::Draw),
            }
        })
        .collect();
    state.request_card_choice(
        sts2_core::ChoiceKind::AddFromDrawByType,
        options,
        1,
        1,
        // `CardSelectorPrefs(prompt, 1)` leaves `Cancelable` false: no skip
        // (sts2-agent fork; the skip also let the search pick an illegal move).
        false,
    );
    EffectResult::Resolved
}

/// Map a card's rarity to the C# `CardRarity` enum ordinal so the grid sort
/// is rarity-primary in the same order the game uses. The Rust `CardRarity`
/// discriminant order (Basic, Common, Uncommon, Rare, Ancient, Status, Curse,
/// Event, Quest) differs from C# `CardRarity.cs` (None=0, Basic=1, Common=2,
/// Uncommon=3, Rare=4, Ancient=5, Event=6, Token=7, Status=8, Curse=9,
/// Quest=10 — Event sorts BEFORE Status/Curse), so we map explicitly rather
/// than casting. An unknown id (no spec) sorts last. Bead `sts2-rs-19hm7`.
fn csharp_rarity_ordinal(card_id: sts2_core::cards::CardId) -> u8 {
    use crate::cards::types::CardRarity;
    match crate::cards::spec_index::rarity_for_card_id(card_id) {
        Some(CardRarity::Basic) => 1,
        Some(CardRarity::Common) => 2,
        Some(CardRarity::Uncommon) => 3,
        Some(CardRarity::Rare) => 4,
        Some(CardRarity::Ancient) => 5,
        Some(CardRarity::Event) => 6,
        Some(CardRarity::Token) => 7,
        Some(CardRarity::Status) => 8,
        Some(CardRarity::Curse) => 9,
        Some(CardRarity::Quest) => 10,
        None => u8::MAX,
    }
}
